//! Golden rows from the reference tmux 3.8, regenerated by
//! `tests/format_cases.sh` into `golden_rows.in`.

use super::{
    EnvScope, EnvVar, FixedWallClock, FormatContext, LoopItem, LoopKeys, SearchFlags, expand_at,
    parse,
};
use std::collections::HashMap;

include!("golden_rows.in");

/// `n` nested true conditionals around `ok`.
fn nest(n: usize) -> String {
    (0..n).fold("ok".to_owned(), |s, _| format!("#{{?@x,{s}}}"))
}

fn r(template: impl Into<String>, expected: impl Into<String>) -> (String, String) {
    (template.into(), expected.into())
}

/// The fixture `format_cases.sh` builds in the reference server.
struct Fixture {
    vars: HashMap<String, String>,
    session: bool,
    /// The target pane's `#{C:...}` results, recorded from the reference.
    searches: HashMap<(String, String), u32>,
}

fn env(name: &str, value: Option<&str>, hidden: bool) -> EnvVar {
    EnvVar {
        name: name.to_owned(),
        value: value.map(str::to_owned),
        hidden,
    }
}

impl FormatContext for Fixture {
    fn get(&self, name: &str) -> Option<String> {
        self.vars.get(name).cloned()
    }

    fn environ(&self, scope: EnvScope) -> Option<Vec<EnvVar>> {
        let client = || {
            vec![
                env("CL1", Some("x"), false),
                env("CL2", Some("y"), false),
                env("HOME", Some("/"), false),
                env("LANG", Some("C.UTF-8"), false),
                env("PATH", Some("/usr/bin:/bin"), false),
                env("SHELL", Some("/bin/sh"), false),
                env("TZ", Some("UTC"), false),
            ]
        };
        match scope {
            // The session got FOO, GONE (removed), HID (hidden) and ZED on top of the
            // update-environment variables of the (empty-environment) client, which
            // `update-environment ''` keeps out.
            EnvScope::Session if self.session => Some(vec![
                env("FOO", Some("bar"), false),
                env("GONE", None, false),
                env("HID", Some("sec"), true),
                env("ZED", Some(""), false),
            ]),
            EnvScope::Session => None,
            EnvScope::Global => {
                let mut v = client();
                v.insert(5, env("PWD", Some("/"), false));
                Some(v)
            }
            EnvScope::Client => Some(client()),
        }
    }

    fn window_name_exists(&self, name: &str) -> Option<bool> {
        self.session.then_some(name == "w")
    }

    fn session_name_exists(&self, name: &str) -> bool {
        self.session && name == "s"
    }

    // One session `s`, its window `w` and pane %0; `set -F` has no client, so no item
    // is active and `L` is empty.
    fn sessions(&self) -> Vec<LoopItem<'_>> {
        if self.session { self.one() } else { Vec::new() }
    }

    fn windows(&self) -> Option<Vec<LoopItem<'_>>> {
        self.session.then(|| self.one())
    }

    fn panes(&self) -> Option<Vec<LoopItem<'_>>> {
        self.session.then(|| self.one())
    }

    fn search_pane(&self, pattern: &str, flags: SearchFlags) -> Option<u32> {
        if !self.session {
            return None; // no pane
        }
        let f = format!(
            "{}{}",
            if flags.regex { "r" } else { "" },
            if flags.ignore_case { "i" } else { "" },
        );
        let n = *self
            .searches
            .get(&(f.clone(), pattern.to_owned()))
            .unwrap_or_else(|| panic!("no recorded search for /{f} {pattern:?}"));
        (n != 0).then_some(n)
    }
}

impl Fixture {
    /// The fixture's single session, window or pane as a loop item.
    fn one(&self) -> Vec<LoopItem<'_>> {
        vec![LoopItem {
            ctx: Box::new(self),
            keys: LoopKeys::default(),
        }]
    }
}

fn fixture() -> Fixture {
    let mut vars: HashMap<String, String> = [
        ("session_name", "s"),
        ("window_name", "w"),
        ("window_index", "0"),
        ("window_flags", "*"),
        ("pane_index", "0"),
        ("pane_id", "%0"),
        ("pane_title", "t"),
    ]
    .into_iter()
    .map(|(k, v)| (k.to_owned(), v.to_owned()))
    .collect();
    vars.extend(
        vars_table()
            .into_iter()
            .map(|(k, v)| (k.to_owned(), v.to_owned())),
    );
    let searches = searches()
        .into_iter()
        .map(|(f, p, n)| ((f.to_owned(), p.to_owned()), n))
        .collect();
    Fixture {
        vars,
        session: true,
        searches,
    }
}

fn vars_table() -> Vec<(&'static str, &'static str)> {
    vars()
}

/// A server with no session: no session variables and no @options.
fn nosession() -> Fixture {
    Fixture {
        vars: HashMap::new(),
        session: false,
        searches: HashMap::new(),
    }
}

fn check(ctx: &Fixture, rows: Vec<(String, String)>) {
    let mut failures = Vec::new();
    for (template, expected) in rows {
        // The reference ran with TZ=UTC; pin the zone and the clock.
        let wall = FixedWallClock::new(1_793_369_398, "UTC").expect("zoneinfo");
        let got = expand_at(&parse(&template).ast, ctx, &wall);
        if got != expected {
            failures.push(format!("{template:?}: expected {expected:?}, got {got:?}"));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn golden_rows_match_reference() {
    check(&fixture(), rows());
}

#[test]
fn golden_rows_without_a_session_match_reference() {
    check(&nosession(), rows_nosession());
}
